'use strict';
const $=s=>document.querySelector(s),START=6,END=24,TZ='Europe/Warsaw';
const weekdays=['pn','wt','śr','czw','pt'],fullDays=['Poniedziałek','Wtorek','Środa','Czwartek','Piątek'],months=['sty','lut','mar','kwi','maj','cze','lip','sie','wrz','paź','lis','gru'];
