3:[L('Język angielski','08:35','09:20','140'),L('IPM10 - Język obcy zawodowy','09:25','10:10','151'),L('Język polski','10:20','11:05','213'),L('Matematyka','11:20','12:05','316'),L('Matematyka','12:15','13:00','316'),L('Historia','13:20','14:05','312')],
